Ext.define('Spt_Sp_JoinPublicAnnouncement.view.joinPublicAnnounce.JoinPublicAnnounceListViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.Spt_Sp_JoinPublicAnnouncementjoinpublicannouncejoinpublicannouncelist',

    init: function() {
        var me = this;
        var view = this.getView();

        me.refreshSearchForm();
        view.search = Ext.Function.bind(me.search, me);


         //2022.10.18 제한경쟁유형 최초 hide KSH.
         var limitedReasonCodeField = me.lookupReference('limitedReasonCodeField');
         var limitedType = me.lookupReference('limitedType');
         limitedType.hide(true);
         limitedReasonCodeField.hide(true);
    },

    refreshSearchForm: function() {
        var me = this,
            vm = me.getViewModel();

        vm.set('searchValue', {searchDateType : 'NoticeDateTime'
                               , searchType : ''
                               ,toSearchDate : new Date()
                               ,fromSearchDate : Ext.Date.add(new Date(), Ext.Date.DAY, -365)});
    },

    search: function() {
        var me = this,
            vm = me.getViewModel(),
            searchValue = vm.get('searchValue'),
            store = me.getStore('JoinPublicAnnounceStore');

        var fields = me.lookupReference('searchform').getForm().getFields().items;
        var returnVal = true;
        var message;
        Ext.each(fields, function(field){
            if(!field.isValid() && returnVal){
                var label = field.fieldLabel == null ? field.up().fieldLabel : field.fieldLabel;
                message = Ext.String.format('#{{0}은(는) 필수 입력입니다.}', label);
                return false;

            }
        });

        if(!message) {
            var datePeriod = Site.util.Format.getCountPeriodDate(searchValue.fromSearchDate,searchValue.toSearchDate);
            if(!datePeriod || datePeriod > 365 ) {
                message = '#{공고일자의 최대 검색기간은 1년(12개월)입니다.}';
            }
        }


        if(message) {
            Etna.Message.alert(message);
            return false;
        }

        me.getView().setLoading(true);
        store.loadPage(1,{
            params : searchValue,
            callback : function() {
                me.getView().setLoading(false);
            }
        });
    },

    onGridCellClick: function(record) {
        var me = this;
        if(record.get('rfxType') === 'ReverseAuction'){
            me.getView().fireEvent('showReverseAuctionDetail', record.get('id'), record.get('vendorAttendId'));
        }else{
            me.getView().fireEvent('showBidDetail', record.get('id'),record.get('rfxType'),record.get('inOutType'),record.get('foreignBidType'),record.get('distributionElecPrivateYN'));
        }

    },

    onSearchButtonClick: function(button, e, eOpts) {
        var me = this;
        me.search();
    },

    onRefreshButtonClick: function(button, e, eOpts) {
        var me = this;

        me.refreshSearchForm();
    },

    onComboboxChange: function(field, newValue, oldValue, eOpts) {

    },

    onTextfieldKeyup: function(textfield, e, eOpts) {
        var me = this,
            vm = me.getViewModel();
        if(vm.get('searchValue.searchType') === 'AnnounceNo') {
            var reg = /\W/g;
            var textValue = vm.get('searchValue.searchText');
            if(reg.test(textValue)) {
                vm.set('searchValue.searchText', textValue.replace(reg, ''));
            }
        }
    },

    onComboboxChange1: function(field, newValue, oldValue, eOpts) {
        var me = this,
            vm = me.getViewModel();

        //ServiceBid (공사)
        //ProductBid (자재입찰)
        //ReverseAuction(역경매)

        //2022.10.18 KSH 입찰방식에 따른 제한경쟁유형 조회

        var  view = me.getView();

        var limitedReasonCodeField = me.lookupReference('limitedReasonCodeField');
        var limitedType = me.lookupReference('limitedType');



        if(newValue === 'ServiceBid') { // 공사입찰

            limitedReasonCodeField.show(true);
            limitedType.hide(true);
            limitedType.setValue('');


        } else if(newValue=='ProductBid') { // 자재입찰

            limitedType.show(true);
            limitedReasonCodeField.hide(true);
            limitedReasonCodeField.setValue('');

        } else { // ReverseAuction(역경매)

            limitedType.hide(true);
            limitedReasonCodeField.hide(true);
        }

        if(limitedReasonCodeField.rendered){
            limitedReasonCodeField.onRender();
        }
        /*------------------END------------------------*/

        var reverseAuctionYN = me.lookupReference('reverseAuctionYN');

        if(newValue === 'ReverseAuction') {
            reverseAuctionYN.setReadOnly(true);
            reverseAuctionYN.setValue(true);




        } else {
            reverseAuctionYN.setReadOnly(false);
            reverseAuctionYN.setValue(false);



        }
    },

    onDatefieldChange: function(field, newValue, oldValue, eOpts) {
        var me = this,
            vm = me.getViewModel();

        vm.set('searchValue.toSearchDate', Ext.Date.add(vm.get('searchValue.fromSearchDate'), Ext.Date.DAY, 365));
    },

    onReverseAuctionYNChange: function(field, newValue, oldValue, eOpts) {
        //2022.11.22 KSH 역경매 선택 시 추정가격,낙찰자결정방법,제한경쟁유형 필터

        var me =  this;

        var limitedReasonCodeField = me.lookupReference('limitedReasonCodeField');
        var limitedType = me.lookupReference('limitedType');
        var price = me.lookupReference('price');
        var bidTypeCombo = me.lookupReference('bidTypeCombo');
        var rank = me.lookupReference('rank');


        if(newValue){
            limitedReasonCodeField.hide(true);
            limitedType.hide(true);
            price.hide(true);
            bidTypeCombo.hide(true);
            rank.hide(true);
            rank.setValue('');

        }else{

            price.show();
            bidTypeCombo.show();
            rank.show();
        }
    },

    onFormSpecialkey: function(form, e) {
        var me = this;
        if(e.getKey() == e.ENTER){
            me.search();
        }
    },

    onGridpanelCellClick: function(tableview, td, cellIndex, record, tr, rowIndex, e, eOpts) {
        var me = this,
            dataIndex = tableview.getColumnManager().getHeaderAtIndex(cellIndex).dataIndex;

        if(dataIndex === 'announceNo'){
            me.onGridCellClick(record);
        }
    },

    onPanelAfterRender: function(component, eOpts) {
        var me = this,
            view = me.getView();
        var searchFieldLastEl = this.getView().down("#reverseAuctionYN").el;
        var firstButton = this.getView().down("#searchButton").el;
        var lastButton = this.getView().down("#resetButton").el;
        var mainGrid = me.getView().down("gridpanel");
        var fromSearchFieldLastEl = false;

        /** 조회조건의 마지막 필드인 경우 */
        searchFieldLastEl.on("keydown", function(e){
            if(e.TAB === e.getKey() && !e.shiftKey) {
                e.preventDefault(); // 네이티브 이벤트 방지
                e.stopPropagation();  // 네이티브 이벤트 방지
                /** 포커싱 가능한 엘리먼트 포커스 */
                firstButton.focus();
                fromSearchFieldLastEl = true;
            }
        });

        /** 툴바버튼의 마지막 버튼인 경우 */
        lastButton.on("keydown", function(e){
            if(e.TAB === e.getKey() && !e.shiftKey) {
                if(fromSearchFieldLastEl) {
                    e.preventDefault(); // 네이티브 이벤트 방지
                    e.stopPropagation(); // 네이티브 이벤트 방지
                    /** 그리드의 경우, 접근가능한(tabindex=0) 엘리먼트를 찾아 포커싱 */
                    if(mainGrid.el) {
                        var tabItems = mainGrid.el.dom.querySelectorAll("[tabindex]");
                        for(var i=0; i<tabItems.length; i++) { // grid locked인
                            if(tabItems[i].parentElement.id.indexOf('locked') === -1) {
                                tabItems[i].setAttribute("tabindex", "0");
                                tabItems[i].focus();
                                fromSearchFieldLastEl = false;
                                return;
                            }
                        }
                    }
                    fromSearchFieldLastEl = false;
                }
            }
        });
    }

});
